def max_turbulence(nums):
    best = cur = 1
    prev_cmp = 0
    for a, b in zip(nums, nums[1:]):
        cmp = (b > a) - (b < a)
        if cmp == 0:
            cur = 1
        elif cmp == -prev_cmp:
            cur += 1
        else:
            cur = 2
        prev_cmp = cmp
        best = max(best, cur)
    return best if nums else 0
